-- ============================================================
-- COVEPA - TABLA DE OBSERVACIONES (ESTRUCTURA EXACTA + FECHA_SUBSANACION)
-- ============================================================

CREATE TABLE IF NOT EXISTS public.observaciones (
    id_obs VARCHAR(80) PRIMARY KEY,
    hito VARCHAR(50),
    id_sitio VARCHAR(50) NOT NULL,
    protocolo VARCHAR(120),
    subsistema VARCHAR(255),
    detalle TEXT,
    item VARCHAR(50),
    sub_item VARCHAR(50),
    comentario_inicial TEXT,
    comentario_complementario TEXT,
    comentario_final TEXT,
    acuerdo_subsanacion TEXT,
    estado_gilat VARCHAR(80),
    estado_covepa VARCHAR(80),
    estado_pronatel VARCHAR(80),
    comentario_pronatel TEXT,
    comentario_covepa TEXT,
    fecha_subsanacion TIMESTAMPTZ
);

-- Políticas de seguridad RLS
ALTER TABLE public.observaciones ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    CREATE POLICY "Permitir todo en observaciones" 
    ON public.observaciones FOR ALL 
    USING (true) 
    WITH CHECK (true);
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

-- Índices para búsqueda rápida
CREATE INDEX IF NOT EXISTS idx_obs_id_sitio ON public.observaciones(id_sitio);
CREATE INDEX IF NOT EXISTS idx_obs_estado_covepa ON public.observaciones(estado_covepa);
CREATE INDEX IF NOT EXISTS idx_obs_estado_pronatel ON public.observaciones(estado_pronatel);
CREATE INDEX IF NOT EXISTS idx_obs_protocolo ON public.observaciones(protocolo);
CREATE INDEX IF NOT EXISTS idx_obs_hito ON public.observaciones(hito);


